#pragma once

#include <OpenModel/Heat1D.hpp>
#include <OpenModel/Heat2D.hpp>

#include <array>
#include <map>
#include <string>
#include <vector>

/**
 * @file Heat2DMesh.hpp
 * @brief Steady two-dimensional thin-plate heat conduction on an unstructured triangle mesh (linear triangles).
 *
 * The mesh is given by the caller (for example generated by Gmsh, see Heat2DGmsh.hpp). Every boundary edge carries an
 * integer tag; each tag names one Boundary condition. A boundary edge whose tag is not in `boundaries` is insulated.
 * The model is the same thin-plate model as Heat2D (see Heat2D.hpp): k(x, y, T) and the source q(x, y, t) are evaluated
 * with 3-point quadrature on each triangle, and the non-linear terms are solved with the Picard iteration. Steady and
 * transient runs (theta method, consistent or lumped capacity) are both available.
 */

namespace OpenModel::Heat2D {

/** @brief An unstructured triangle mesh with tagged boundary edges. */
struct TriangleMesh {
    std::vector<std::array<double, 2>> nodes;     ///< Node coordinates (x, y).
    std::vector<std::array<int, 3>> triangles;    ///< Node indices of each triangle, 0-based.

    /// A boundary edge between two nodes. The tag selects a condition in MeshModel::boundaries.
    struct BoundaryEdge {
        int a = 0;
        int b = 0;
        int tag = 0;
    };
    std::vector<BoundaryEdge> edges;              ///< Edges of the outer boundary and of the holes.
};

/** @brief Properties and conditions on the mesh. */
struct MeshModel {
    double thickness = 1.0;                       ///< Thickness along z, > 0.
    Conductivity2 conductivity;                   ///< k(x, y, T) > 0. Required.
    Source2 source;                               ///< q(x, y, t). Empty = none.
    Field2 volumetricHeatCapacity;                ///< rho c_p(x, y) > 0. Required for a transient run.
    Field2 initialTemperature;                    ///< T(x, y) at t = 0 for a transient run. Empty = 0 everywhere.
    /// Condition of each boundary tag. Tags missing here are insulated.
    std::map<int, Heat1D::Boundary> boundaries;
    double stefanBoltzmann = 5.670374419e-8;      ///< sigma, in the unit system of the model.
};

/** @brief Result of a steady run on a mesh. */
struct MeshResult {
    std::string error;                            ///< Empty on success.
    bool converged = false;                       ///< True when every step reached the Picard tolerance.
    int maxPicardIterations = 0;                  ///< Largest number of Picard iterations used by one step.
    std::vector<double> times;                    ///< Recorded times (a single 0 for a steady run).
    /// temperatures[k][i] = temperature of node i at times[k], in the order of TriangleMesh::nodes.
    std::vector<std::vector<double>> temperatures;
};

/**
 * @brief Checks the mesh and the model.
 * @return an empty string when usable, otherwise the first problem found.
 */
std::string validateMesh(const TriangleMesh& mesh, const MeshModel& model);

/**
 * @brief Solves the problem on the mesh: steady when Options::steady is true, otherwise transient with the theta method
 *        (Options::theta, timeStep, endTime, capacity, recordEvery). Invalid input and failed iterations are reported in
 *        MeshResult::error, with no exception.
 */
MeshResult solveMesh(const TriangleMesh& mesh, const MeshModel& model, const Options& options);

} // namespace OpenModel::Heat2D
